window.BADMIN_DATA = {"PAGES":[{"id":"home","n":"Home","grp":"Pages","path":"#home","pv":"hero","f":[["h","Headline","Talk to someone\nwho's already there.","m"],["lede","Intro","Verified alumni and current students from India's design schools: all 19 NIFT campuses, the NIDs and the IITs that teach design. Find someone from your branch and ask them about entrances, portfolios, campus life or work.","m"],["b1","Main button","Sign up"],["b2","Second button","Log in"]]},{"id":"login","n":"Log in","grp":"Pages","path":"#login","pv":"head","g":1,"f":[["eb","Eyebrow","Log in"],["h","Heading","Welcome back"],["lede","Intro","Use the Google account you joined with. There's no password to remember.","m"],["b1","Google button","Sign in with Google"]]},{"id":"faculty","n":"Faculty sign-in","grp":"Pages","path":"#login","pv":"head","f":[["eb","Eyebrow","Faculty sign-in"],["h","Heading","Sign in with your faculty ID"],["lede","Intro","Faculty accounts are set up by the Bridges team. Your ID and password are in the email they sent you.","m"],["b1","Button","Sign in"]]},{"id":"join","n":"Sign up","grp":"Pages","path":"#join","pv":"head","g":1,"f":[["eb","Eyebrow","Sign up"],["h","Heading","Join Bridges.directory"],["lede","Intro","Current students and alumni both get listed.","m"],["b1","Google button","Sign up with Google"],["start","First step","Sign in with Google to start, then set up your profile. There's no password to create.","m"]]},{"id":"directory","n":"Directory","grp":"Pages","path":"#directory","pv":"head","f":[["eb","Eyebrow","Directory"],["h","Heading","Find someone a few steps ahead"],["lede","Intro","Verified students and alumni from India's design schools. You can open a few contacts each week, so inboxes stay usable.","m"]]},{"id":"contribute","n":"Contribute","grp":"Pages","path":"#contribute","pv":"head","f":[["eb","Eyebrow","Contribute"],["h","Heading","Help keep it free"],["lede","Intro","Keeping this platform free and accessible to everyone costs {goal} each year. If it has been useful to you, please consider contributing. Every contribution, large or small, helps us keep it running.","m"],["b1","Button","Contribute"]]},{"id":"footer","n":"Footer","grp":"Pages","path":"#home","pv":"footer","f":[["about","About text","A free, verified directory of students and alumni from India's design schools: all 19 NIFT campuses, the NIDs and the IITs that teach design. Built by students, kept running by contributions.","m"]]},{"id":"notify","n":"Notifications","grp":"Messages","path":"","pv":"toast","f":[["in_t","Signed in: title","Welcome back, {first}"],["in","Signed in: message","Signed in as {name} with {account}."],["out_t","Logged out: title","Logged out"],["out","Logged out: message","See you next time."],["list_t","Listed: title","You're listed"],["list","Listed: message","Email confirmed. You're listed."]]},{"id":"emails","n":"Emails","grp":"Messages","path":"","pv":"email","f":[["fac_s","Faculty welcome: subject","Your Bridges.directory faculty account"],["fac_b","Faculty welcome: body","Hello {name},\n\nThe Bridges team has set up a faculty account for you on Bridges.directory.\n\nFaculty ID: {id}\nPassword: {password}\n\nSign in at bridges.directory with Faculty sign-in. Your profile isn't listed in the directory, and only the Bridges team can change it or reset your password.\n\nThe Bridges team","m"],["code_s","Verification code: subject","Your Bridges.directory code: {code}"],["inv_s","Invite: subject","{first} invited you to Bridges.directory"],["ref_s","Referral: subject","Your Bridges.directory referral code"]]},{"id":"doc-about","n":"About","grp":"About and legal","path":"#about","pv":"legal","eb":"About","f":[["t","Title","A few steps ahead, one message away"],["lede","Intro","Bridges.directory is a free, verified directory of students and alumni from India’s design schools. It exists so that anyone preparing for an entrance, building a portfolio or choosing a specialisation can ask someone who has already done it.","m"],["body","Page body (HTML)","<h3>Who’s listed</h3>\n<p>Current students and alumni of all 19 NIFT campuses, the NIDs, and the IITs that teach design. Everyone is verified before they appear, so the person you write to really did study where they say.</p>\n<h3 id=\"verify\">How verification works</h3>\n<ul>\n<li><b>Students</b> get a one-time code at their institute email. Anyone without one can upload a bonafide certificate instead.</li>\n<li><b>Alumni</b> upload a degree certificate or alumni ID, or enter a referral code from a verified alum of the same institute.</li>\n<li><b>Certificates</b> are checked by two student volunteers. They see only your name, institute, branch and year; everything else is hidden, and the file is deleted once they decide.</li>\n</ul>\n<h3>How contact works</h3>\n<p>Signed-in members can open up to five contacts a week. The count resets every Monday at midnight IST. The limit keeps inboxes manageable for the people who help, so please make each message count.</p>\n<h3>Who runs it</h3>\n<p>A small team of design students, with current students volunteering to review certificates. Running costs are about ₹10,000 a year, covered by contributions from members. There are no ads, and we never sell data.</p>\n<h3>Get in touch</h3>\n<p>Write to <a href=\"mailto:hello@bridges.directory\">hello@bridges.directory</a>. To report a listing, use <b>Report</b> on that person’s card, or write to <a href=\"mailto:safety@bridges.directory\">safety@bridges.directory</a>.</p>","h"]]},{"id":"doc-privacy","n":"Privacy policy","grp":"About and legal","path":"#privacy","pv":"legal","eb":"Legal","f":[["t","Title","Privacy policy"],["lede","Intro","What we collect, why, who can see it, and how to take it back.","m"],["body","Page body (HTML)","<h3>1. Who we are</h3>\n<p>Bridges.directory (“we”) is run by [legal name of the team or entity, to be confirmed]. Under India’s Digital Personal Data Protection Act, 2023, we are the data fiduciary for the personal data described here.</p>\n<h3>2. What we collect</h3>\n<ul>\n<li><b>Your listing:</b> name, institute and campus, branch, batch or expected graduation year, what you’re happy to help with, your avatar, an optional portfolio link and, for alumni, your experience.</li>\n<li><b>Your Google account:</b> when you sign in with Google, we receive your name and email address, and Google’s confirmation that the address is yours. We never see your Google password.</li>\n<li><b>Contact details:</b> your institute email (students), and for alumni, a contact email if you set one.</li>\n<li><b>Verification:</b> the certificate you upload or the referral code you enter, and a record of the method and the outcome.</li>\n<li><b>Volunteers:</b> your mobile number.</li>\n<li><b>Contributions:</b> the amount, the date and the name you choose to show, or “Anonymous”. Payments are handled by our payment provider; we never see or store card or UPI details.</li>\n<li><b>Activity:</b> which contacts you have opened, to apply the weekly limit. With your consent, anonymous page counts.</li>\n</ul>\n<h3>3. Why we use it</h3>\n<p>To verify and list you, to let signed-in members contact you within the weekly limit, to run the volunteer programme, to process contributions, to keep the platform free of spam and misuse, and, only if you allow it, to understand which pages help.</p>\n<h3>4. Consent</h3>\n<p>We process your data on the basis of the consent you give when you sign up, and for uses the law permits without consent, such as responding to legal requests. You can withdraw consent at any time by deleting your account; we then stop listing you.</p>\n<h3>5. Who can see what</h3>\n<ul>\n<li>Listings are visible only to signed-in, verified members, not to search engines or visitors.</li>\n<li>Your email and portfolio link are shown only when a member chooses to open your contact, which uses one of their five contacts that week.</li>\n<li>Volunteers see only name, institute, branch and year from a certificate. Your volunteer number is shared with coordinators and the volunteer WhatsApp group.</li>\n<li>Faculty accounts, created by the Bridges team, can browse and open contacts like members, but aren’t listed themselves.</li>\n<li>Service providers that host the site, handle Google sign-in, send email and process payments handle data for us under contract. We never sell or rent data, and we don’t share it with advertisers.</li>\n</ul>\n<h3>6. How long we keep it</h3>\n<ul>\n<li>Certificates are deleted as soon as a decision is made.</li>\n<li>Your listing stays while your account is active.</li>\n<li>When you delete your account, your listing disappears at once and your data is erased within 30 days, except records the law requires us to keep, such as contribution receipts.</li>\n</ul>\n<h3>7. Your rights</h3>\n<ul>\n<li><b>Access:</b> download a copy of your data from My profile.</li>\n<li><b>Correction:</b> change your details at any time with Edit profile.</li>\n<li><b>Erasure:</b> delete your account from My profile.</li>\n<li><b>Nomination:</b> name someone to exercise these rights for you if you can’t.</li>\n<li><b>Grievances:</b> write to our grievance officer (below).</li>\n</ul>\n<h3>8. Age</h3>\n<p>You must be 18 or older to sign up, or have verifiable consent from a parent or guardian.</p>\n<h3>9. Security</h3>\n<p>Data is encrypted in transit, access is limited to the people who need it, and volunteers only ever see redacted files.</p>\n<h3>10. Grievance officer</h3>\n<p>[Name], <a href=\"mailto:grievances@bridges.directory\">grievances@bridges.directory</a>. We acknowledge complaints within 24 hours and aim to resolve them within 15 days. If you’re not satisfied, you can complain to the Data Protection Board of India.</p>\n<h3>11. Changes</h3>\n<p>We’ll post updates here, and tell you by email or on the site before any significant change takes effect.</p>","h"]]},{"id":"doc-terms","n":"Terms of use","grp":"About and legal","path":"#terms","pv":"legal","eb":"Legal","f":[["t","Title","Terms of use"],["lede","Intro","The rules for using Bridges.directory. Creating an account means you agree to them and to the Privacy policy.","m"],["body","Page body (HTML)","<h3>1. Who can join</h3>\n<ul>\n<li>Current students and alumni of the institutes listed on the site. Faculty accounts are created by the Bridges team on request.</li>\n<li>You must be 18 or older, or have consent from a parent or guardian.</li>\n<li>One account per person, and everything in your listing must be true.</li>\n</ul>\n<h3>2. Verification and referrals</h3>\n<p>We may refuse or remove any listing we can’t verify. Refer only people you know studied at your institute. Misusing referrals can lead to both accounts being removed.</p>\n<h3>3. Using contact details</h3>\n<p>Use them only to ask for help, advice or opportunities related to design education and careers. Don’t:</p>\n<ul>\n<li>send bulk or copy-pasted messages, or add people to mailing lists;</li>\n<li>copy, scrape, sell or publish anyone’s details;</li>\n<li>promote products, services or unrelated schemes;</li>\n<li>harass anyone, or keep writing after they’ve said no.</li>\n</ul>\n<p>The weekly contact limit is part of these terms. Don’t try to get around it.</p>\n<h3>4. Volunteers</h3>\n<p>Keep everything you see while reviewing confidential. Decide honestly, and don’t download, copy or share certificates.</p>\n<h3>5. Your listing</h3>\n<p>You’re responsible for what you add, and you allow us to show it to signed-in members. You can edit or delete it at any time.</p>\n<h3>6. Contributions</h3>\n<p>Contributions are voluntary and pay for running costs; they don’t buy anything. They’re refundable only for duplicate or mistaken payments reported within 7 days. They’re not tax-deductible unless we say so in writing.</p>\n<h3>7. Suspension</h3>\n<p>We may limit or suspend accounts that break these terms or the Community guidelines, and we’ll tell you why.</p>\n<h3>8. No guarantees</h3>\n<p>Bridges.directory connects people. We don’t guarantee that anyone will reply, and advice from members is their own. Nothing here promises admission, a job or an internship.</p>\n<h3>9. Liability</h3>\n<p>As far as the law allows, we aren’t liable for indirect losses, and our total liability to you is limited to what you contributed in the previous 12 months.</p>\n<h3>10. Law</h3>\n<p>These terms are governed by the laws of India, and the courts at [city, to be confirmed] have jurisdiction.</p>\n<h3>11. Changes and contact</h3>\n<p>We’ll post updates here and tell you about significant ones. Questions: <a href=\"mailto:hello@bridges.directory\">hello@bridges.directory</a>.</p>","h"]]},{"id":"doc-cookies","n":"Cookie policy","grp":"About and legal","path":"#cookies","pv":"legal","eb":"Legal","f":[["t","Title","Cookie policy"],["lede","Intro","We keep this short because we use very little. There are no advertising or social-media cookies.","m"],["body","Page body (HTML)","<h3>What we store</h3>\n<p>Cookies and similar browser storage are small pieces of data kept on your device. Here’s everything Bridges.directory stores:</p>\n<div class=\"doc-tbl\" role=\"table\" aria-label=\"Cookies and storage\">\n<div role=\"row\" class=\"th\"><span role=\"columnheader\">Name</span><span role=\"columnheader\">Why</span><span role=\"columnheader\">Kept for</span></div>\n<div role=\"row\"><span role=\"cell\"><code>bridges-session</code><small>Essential</small></span><span role=\"cell\">Keeps you logged in.</span><span role=\"cell\">Until you log out</span></div>\n<div role=\"row\"><span role=\"cell\"><code>Google sign-in</code><small>Essential</small></span><span role=\"cell\">Set by Google while you sign in, so it can confirm your account. Covered by Google’s own privacy policy.</span><span role=\"cell\">Set by Google</span></div>\n<div role=\"row\"><span role=\"cell\"><code>bridges-theme</code><small>Essential</small></span><span role=\"cell\">Remembers light, dark or system appearance.</span><span role=\"cell\">Until you change it</span></div>\n<div role=\"row\"><span role=\"cell\"><code>bridges-consent</code><small>Essential</small></span><span role=\"cell\">Remembers your cookie choice, so we don’t ask again.</span><span role=\"cell\">12 months</span></div>\n<div role=\"row\"><span role=\"cell\"><code>Analytics</code><small>Optional</small></span><span role=\"cell\">Anonymous page counts. No cross-site tracking, and IP addresses aren’t stored.</span><span role=\"cell\">Only if you allow it</span></div>\n</div>\n<h3>Your choice</h3>\n<p>Essential storage is needed for the site to work, so it’s always on. Analytics stay off until you allow them. Change your mind any time with <b>Cookie settings</b> at the bottom of every page, or clear this site’s data in your browser.</p>","h"]]},{"id":"doc-guidelines","n":"Community guidelines","grp":"About and legal","path":"#guidelines","pv":"legal","eb":"Community","f":[["t","Title","Community guidelines"],["lede","Intro","Everyone here is giving their time for free. These guidelines keep it worth giving.","m"],["body","Page body (HTML)","<h3>When you reach out</h3>\n<ul>\n<li><b>Be specific.</b> Say who you are, what you’re working on and what you need. “Can you look at my portfolio?” gets fewer replies than a clear question.</li>\n<li><b>Respect people’s time.</b> Send one message and follow up once. If someone says no or doesn’t reply, let it go.</li>\n<li><b>Keep it about design education and careers.</b> No sales, promotions or recruiting for unrelated work.</li>\n</ul>\n<h3>On your listing</h3>\n<ul>\n<li>Be honest about where you studied and what you do.</li>\n<li>Only tick what you’re actually happy to help with, and update it when that changes.</li>\n</ul>\n<h3>Always</h3>\n<ul>\n<li>Don’t share anyone’s contact details or messages outside the platform without their permission.</li>\n<li>No harassment, discrimination or hate, in any form.</li>\n</ul>\n<h3>Reporting</h3>\n<p>Use <b>Report</b> on any card, or write to <a href=\"mailto:safety@bridges.directory\">safety@bridges.directory</a>. We review every report within 3 days, and the person isn’t told who reported them.</p>\n<h3>What happens</h3>\n<p>Depending on what happened: a warning, a lower contact limit, or removal from the directory.</p>","h"]]}],"OPEN":["Portfolio review","Mentorship call","Internship leads","Referrals","Entrance prep","Campus life","Something else"],"OPEN_FOR":{"alum":[0,1,2,3,6],"student":[0,4,5,1,6]}};
